#!/bin/bash
# ============================================================
#  Dolphin Rt:Core v12 — Universal Launcher  (muOS 2606 "Andromeda")
#  SPDW Factory Lab / sirpips aka SilverCrow2323
#  /opt/muos/script/launch/ext-dolphinrt.sh
# ============================================================
#  Called by the muOS frontend as:  ext-dolphinrt.sh <NAME> <CORE> <ROM>
#  CORE is the "core" field of the manifest entry:  ext-dolphin-<profile>-[upright|sideways]
#  (entries are generated by RtSys/manifest_tool.sh from switch_weapon/*.ini)
# ============================================================
. /opt/muos/script/var/func.sh

NAME=$1
CORE=$2
ROM=${3%/}

# ── Parse CORE ─────────────────────────────────────────────
ORIENT="upright"
case "$CORE" in *-sideways) ORIENT="sideways" ;; esac
PROFILE=$(echo "$CORE" | sed -E 's/^ext-dolphin-//; s/-(upright|sideways)$//')
[ -z "$PROFILE" ] && PROFILE="default"

# ── Environment ────────────────────────────────────────────
NUMSTICKS="$(GET_VAR "device" "board/stick" 2>/dev/null)"
case "$NUMSTICKS" in ''|*[!0-9]*) NUMSTICKS=0 ;; esac

HOME_VAL="$(GET_VAR "device" "board/home" 2>/dev/null)"
[ -n "$HOME_VAL" ] && export HOME="$HOME_VAL"
export XDG_CONFIG_HOME="$HOME/.config"

EMUDIR="$MUOS_SHARE_DIR/emulator/dolphin"
[ -d "$EMUDIR" ] || EMUDIR="/opt/muos/share/emulator/dolphin"
RTSYS="$EMUDIR/RtSys"
LOG="$RTSYS/logs/launcher.log"
mkdir -p "$RTSYS/logs"

[ -x "$EMUDIR/dolphin" ] || chmod +x "$EMUDIR/dolphin" 2>/dev/null
if [ ! -x "$EMUDIR/dolphin" ]; then
    echo "$(date '+%F %T') | [FATAL] $EMUDIR/dolphin missing or not executable" >> "$LOG"
    exit 1
fi

SETUP_SDL_ENVIRONMENT
SET_VAR "system" "foreground_process" "dolphin"      # muOS quit hotkeys / proc_die act on this

# ── Apply profile ──────────────────────────────────────────
"$RTSYS/apply_profile.sh" "$PROFILE" "$ORIENT" "$NUMSTICKS" \
    || { echo "$(date '+%F %T') | [FATAL] apply_profile failed" >> "$LOG"; exit 1; }

# ── Launch ─────────────────────────────────────────────────
echo "$(date '+%F %T') | $PROFILE | $ORIENT | $(basename "$ROM")" >> "$LOG"

cd "$EMUDIR" || exit 1

# Optional extra exit watcher (the native muOS quit hotkey keeps working without it)
JS_DEV=$(ls /dev/input/js* 2>/dev/null | head -n 1)
[ -z "$JS_DEV" ] && JS_DEV="/dev/input/js0"
WATCHER_PID=""
if [ -x "$RTSYS/overlay_exit.sh" ]; then
    "$RTSYS/overlay_exit.sh" "$JS_DEV" >/dev/null 2>&1 &
    WATCHER_PID=$!
fi

cleanup() {
    [ -n "$WATCHER_PID" ] && kill -TERM "$WATCHER_PID" 2>/dev/null
    exit 0
}
trap cleanup TERM INT

# muOS runs Dolphin directly on the framebuffer with the Mali OpenGL ES driver.
./dolphin --platform=fbdev --video_backend=OGL -e "$ROM" -u "$EMUDIR" >> "$RTSYS/logs/dolphin_debug.log" 2>&1
EXIT_CODE=$?

[ -n "$WATCHER_PID" ] && kill -TERM "$WATCHER_PID" 2>/dev/null
echo "$(date '+%F %T') | exit=$EXIT_CODE" >> "$LOG"
exit $EXIT_CODE
